DROP TABLE IF EXISTS `sys_video_episode`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sys_video_episode` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `video_id` bigint NOT NULL COMMENT '鍏宠仈瑙嗛?ID',
  `episode_number` int NOT NULL COMMENT '闆嗘暟',
  `episode_title` varchar(200) DEFAULT '' COMMENT '鍒嗛泦鏍囬?',
  `video_url` varchar(1000) NOT NULL COMMENT '鍒嗛泦鎾?斁鍦板潃',
  `duration` varchar(20) DEFAULT '' COMMENT '鍒嗛泦鏃堕暱',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '鍒涘缓鏃堕棿',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_video_episode` (`video_id`,`episode_number`),
  KEY `idx_video_id` (`video_id`)
) ENGINE=InnoDB AUTO_INCREMENT=37 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='瑙嗛?鍒嗛泦琛';
